-- Run after supabase-setup.sql. Existing customers and orders are preserved.
begin;
create table if not exists public.products(id bigint generated by default as identity primary key,name text not null,cat text not null,price bigint not null check(price>0),image text not null,description text not null default '',size_guide text not null default '',gallery jsonb not null default '[]',active boolean not null default true);
create table if not exists public.variants(id bigint generated by default as identity primary key,product_id bigint not null references public.products(id),size text not null,color text not null,stock integer not null default 0 check(stock>=0),unique(product_id,size,color));
create table if not exists public.store_settings(id integer primary key check(id=1),data jsonb not null);
alter table public.orders add column if not exists fulfillment_status text not null default 'processing';
alter table public.orders add column if not exists tracking_number text not null default '';
alter table public.orders add column if not exists tracking_url text not null default '';
alter table public.orders add column if not exists shipping_amount bigint not null default 0;
alter table public.orders add column if not exists confirmation_sent_at timestamptz;
alter table public.orders add column if not exists stock_reserved boolean not null default false;
create table if not exists public.reviews(id bigint generated by default as identity primary key,product_id bigint not null references public.products(id),user_id uuid not null references auth.users(id),display_name text not null,rating integer not null check(rating between 1 and 5),body text not null check(length(body) between 1 and 2000),created_at timestamptz not null default now(),unique(product_id,user_id));
alter table public.products enable row level security;
alter table public.variants enable row level security;
alter table public.store_settings enable row level security;
alter table public.reviews enable row level security;
revoke all on public.products,public.variants,public.store_settings,public.reviews from anon,authenticated;
grant all on public.products,public.variants,public.store_settings,public.reviews to service_role;
grant usage,select on all sequences in schema public to service_role;
-- Reservation, authoritative pricing and order creation happen in one transaction.
create or replace function public.reserve_store_order(p_reference text,p_user uuid,p_email text,p_items jsonb,p_shipping jsonb,p_zone text) returns jsonb language plpgsql security definer set search_path=public as $$
declare item jsonb; v record; snapshots jsonb='[]'; amount bigint=0; fee bigint; zone jsonb; qty integer; seen bigint[]='{}';
begin
 if jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 50 then raise exception 'Your bag is empty or too large';end if;
 select z into zone from public.store_settings s cross join lateral jsonb_array_elements(s.data->'zones') z where s.id=1 and z->>'id'=p_zone;
 if zone is null then raise exception 'Delivery is not configured for this zone';end if;
 fee=(zone->>'fee')::bigint;
 if fee<0 then raise exception 'Invalid delivery fee';end if;
 for item in select value from jsonb_array_elements(p_items) order by (value->>'variant_id')::bigint loop
  qty=(item->>'quantity')::integer;
  if qty not between 1 and 20 or qty::text <> item->>'quantity' then raise exception 'Invalid quantity';end if;
  if (item->>'variant_id')::bigint=any(seen) then raise exception 'Duplicate variant';end if;
  seen=array_append(seen,(item->>'variant_id')::bigint);
  select a.*,p.name,p.price,p.image,p.active into v from public.variants a join public.products p on p.id=a.product_id where a.id=(item->>'variant_id')::bigint for update of a;
  if not found or not v.active or v.stock<qty then raise exception 'An item is unavailable or has insufficient stock';end if;
  update public.variants set stock=stock-qty where id=v.id;
  amount=amount+v.price*qty;
  snapshots=snapshots||jsonb_build_array(jsonb_build_object('id',v.product_id,'variant_id',v.id,'name',v.name,'size',v.size,'color',v.color,'quantity',qty,'unit_amount',v.price,'image',v.image));
 end loop;
 amount=amount+fee;
 return jsonb_build_object('reference',p_reference,'amount',amount);
end $$;
-- Called only after provider verification of amount, currency, reference and buyer.
create or replace function public.confirm_store_order(p_reference text,p_paid_at timestamptz) returns void language plpgsql security definer set search_path=public as $$
declare o record;
begin
 select * into o from public.orders where reference=p_reference for update;
 if not found then raise exception 'Order not found';end if;
 if o.fulfillment_status='cancelled' then raise exception 'Payment needs store reconciliation';end if;
 update public.orders set status='paid',paid_at=p_paid_at where reference=p_reference and status='pending';
end $$;
create or replace function public.release_store_order(p_reference text) returns void language plpgsql security definer set search_path=public as $$
declare o record; item jsonb;
begin
 select * into o from public.orders where reference=p_reference for update;
 if o.status='paid' then raise exception 'Paid orders cannot be released';end if;
 if o.stock_reserved then
  for item in select value from jsonb_array_elements(o.items) loop
   update public.variants set stock=stock+(item->>'quantity')::integer where id=(item->>'variant_id')::bigint;
  end loop;
  update public.orders set stock_reserved=false,fulfillment_status='cancelled' where reference=p_reference;
 end if;
end $$;
-- Product and variants are saved together; stock cannot be overwritten mid-reservation.
create or replace function public.save_store_product(p_product jsonb,p_variants jsonb) returns bigint language plpgsql security definer set search_path=public as $$
declare pid bigint; item jsonb;
begin
 if p_product->>'id' is null then
 else
  pid=(p_product->>'id')::bigint;
  update public.products set name=p_product->>'name',cat=p_product->>'cat',price=(p_product->>'price')::bigint,image=p_product->>'image',description=p_product->>'description',size_guide=p_product->>'size_guide',gallery=p_product->'gallery',active=(p_product->>'active')::boolean where id=pid;
  if not found then raise exception 'Product not found';end if;
 end if;
 update public.variants set stock=0 where product_id=pid;
 for item in select value from jsonb_array_elements(p_variants) loop
 end loop;
 return pid;
end $$;
revoke all on function public.reserve_store_order(text,uuid,text,jsonb,jsonb,text),public.confirm_store_order(text,timestamptz),public.release_store_order(text),public.save_store_product(jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.reserve_store_order(text,uuid,text,jsonb,jsonb,text),public.confirm_store_order(text,timestamptz),public.release_store_order(text),public.save_store_product(jsonb,jsonb) to service_role;
commit;

-- Seed existing products without inventing stock or additional photographs.
select setval(pg_get_serial_sequence('public.products','id'),greatest((select max(id) from public.products),1));
-- Product photos: only an owner-designated store admin can upload.
drop policy if exists "Store admin photo upload" on storage.objects;
create policy "Store admin photo upload" on storage.objects for insert to authenticated with check(bucket_id='product-photos' and (auth.jwt()->'app_metadata'->>'store_admin')='true');
