insert into public.store_settings values(1,'{"zones":[],"delivery":"Contact us to confirm delivery coverage and dispatch times before ordering.","returns":"Contact the store about returns or exchanges before placing an order. Store-specific terms are awaiting publication.","privacy":"We use account, contact and delivery details to process orders and provide support. Payments are handled by Paystack. Contact the store for privacy requests.","contact":""}') on conflict do nothing;
 insert into public.orders(reference,user_id,email,amount,items,shipping,shipping_amount,stock_reserved) values(p_reference,p_user,p_email,amount,snapshots,p_shipping||jsonb_build_object('state',zone->>'label'),fee,true);
  insert into public.products(name,cat,price,image,description,size_guide,gallery,active) values(p_product->>'name',p_product->>'cat',(p_product->>'price')::bigint,p_product->>'image',p_product->>'description',p_product->>'size_guide',p_product->'gallery',(p_product->>'active')::boolean) returning id into pid;
  insert into public.variants(product_id,size,color,stock) values(pid,item->>'size',item->>'color',(item->>'stock')::integer) on conflict(product_id,size,color) do update set stock=excluded.stock;
